//! Wolfram spectra replay: eigenvalues, residuals and inertia.
//!
//! The fixture (`sonium-qa/wolfram/goldens/exact-linear-algebra-v1.json`,
//! generated by `sonium-qa/wolfram/exact_linear_algebra.wls`) carries exact
//! spectra with inertia triples, per audit-sonium-solvers-eigen-20260921
//! (exact eigenpairs with multiplicities, degenerate/clustered modes) and
//! the inertia ask in audit-sonium-solvers-direct-20260921. Inertia is
//! certified through eigenvalue signs since no separate inertia API exists.
//! The matrix-function fixture
//! (`sonium-qa/wolfram/goldens/matrix-functions-v1.json`, generated by
//! `sonium-qa/wolfram/matrix_functions.wls`) carries nonsymmetric spectra
//! (real and complex-conjugate) for the Francis-QR eigensolver.

use num_complex::Complex64;
use serde::Deserialize;
use sonium_solvers_core::dense::DenseMatrix;
use sonium_solvers_eigen::{nonsymmetric_eigenvalues, symmetric_eigen};

const FIXTURE: &str =
    include_str!("../../../../../crates/sonium-qa/wolfram/goldens/exact-linear-algebra-v1.json");
const MATRIX_FUNCTIONS: &str =
    include_str!("../../../../../crates/sonium-qa/wolfram/goldens/matrix-functions-v1.json");

#[derive(Debug, Deserialize)]
struct SpectraCase {
    a: Vec<Vec<String>>,
    eigenvalues: Vec<String>,
    inertia: [usize; 3],
}

#[derive(Debug, Deserialize)]
struct Fixture {
    schema: String,
    tridiag_3x3: SpectraCase,
    hilbert_4x4: SpectraCase,
    sym_indef_2x2: SpectraCase,
}

fn parse(value: &str) -> f64 {
    value.parse().expect("fixture value is a decimal")
}

fn parse_fixture() -> Fixture {
    let fixture: Fixture =
        serde_json::from_str(FIXTURE).expect("valid exact linear-algebra fixture");
    assert_eq!(fixture.schema, "sonium-qa.exact-linear-algebra.v1");
    fixture
}

fn dense(rows: &[Vec<String>]) -> DenseMatrix<f64> {
    let flat: Vec<f64> = rows
        .iter()
        .flat_map(|row| row.iter().map(|value| parse(value)))
        .collect();
    DenseMatrix::from_row_major_vec(rows.len(), rows[0].len(), flat)
}

/// Sorted eigenvalues, eigenvector residuals and inertia signs.
fn check_spectra(label: &str, case: &SpectraCase) {
    let matrix = dense(&case.a);
    let n = case.a.len();
    let (unsorted_values, vectors) =
        symmetric_eigen(&matrix, n).expect("symmetric_eigen converged");
    assert_eq!(unsorted_values.len(), n);
    let mut values = unsorted_values.clone();
    values.sort_by(|a, b| a.partial_cmp(b).unwrap());
    let expected: Vec<f64> = case.eigenvalues.iter().map(|value| parse(value)).collect();
    for (index, (got, want)) in values.iter().zip(expected.iter()).enumerate() {
        assert!(
            (got - want).abs() <= 1e-9 * want.abs().max(1.0),
            "{label} lambda[{index}]: {got:e} != {want:e}"
        );
    }
    // Eigenvector residuals through the returned column layout, paired with
    // the unsorted eigenvalues from the same call.
    let cols = vectors.ncols();
    assert_eq!(vectors.nrows(), n);
    let data = vectors.as_slice();
    let mut order: Vec<(f64, usize)> = unsorted_values
        .into_iter()
        .enumerate()
        .map(|(i, v)| (v, i))
        .collect();
    order.sort_by(|a, b| a.0.partial_cmp(&b.0).unwrap());
    for (sorted_index, (lambda, col)) in order.iter().enumerate() {
        let mut residual = 0.0;
        let mut norm = 0.0;
        for i in 0..n {
            let mut ax = 0.0;
            for j in 0..n {
                ax += matrix.as_slice()[i * n + j] * data[j * cols + col];
            }
            let diff = ax - lambda * data[i * cols + col];
            residual += diff * diff;
            norm += data[i * cols + col] * data[i * cols + col];
        }
        assert!(
            residual.sqrt() <= 1e-9 * norm.sqrt().max(1.0),
            "{label} eigenvector[{sorted_index}] residual"
        );
    }
    // Inertia from eigenvalue signs.
    let (mut pos, mut neg, mut zero) = (0, 0, 0);
    for value in values {
        if value > 1e-12 {
            pos += 1;
        } else if value < -1e-12 {
            neg += 1;
        } else {
            zero += 1;
        }
    }
    assert_eq!(
        [pos, neg, zero],
        case.inertia,
        "{label}: inertia {pos}/{neg}/{zero} != wolfram {:?}",
        case.inertia
    );
}

#[test]
fn tridiagonal_spectrum_matches_wolfram() {
    let fixture = parse_fixture();
    check_spectra("tridiag_3x3", &fixture.tridiag_3x3);
}

#[test]
fn hilbert_spectrum_matches_wolfram() {
    let fixture = parse_fixture();
    check_spectra("hilbert_4x4", &fixture.hilbert_4x4);
}

#[test]
fn indefinite_spectrum_matches_wolfram() {
    let fixture = parse_fixture();
    check_spectra("sym_indef_2x2", &fixture.sym_indef_2x2);
}

#[derive(Debug, Deserialize)]
struct ComplexScalar {
    re: String,
    im: String,
}

#[derive(Debug, Deserialize)]
struct NonsymSpectraCase {
    a: Vec<Vec<String>>,
    eigenvalues: Vec<ComplexScalar>,
}

#[derive(Debug, Deserialize)]
struct MatrixFunctionsFixture {
    schema: String,
    nonsym_eig_4x4: NonsymSpectraCase,
    companion_eig_3x3: NonsymSpectraCase,
}

fn parse_complex(value: &ComplexScalar) -> Complex64 {
    Complex64::new(parse(&value.re), parse(&value.im))
}

fn parse_matrix_functions() -> MatrixFunctionsFixture {
    let fixture: MatrixFunctionsFixture =
        serde_json::from_str(MATRIX_FUNCTIONS).expect("valid matrix-functions fixture");
    assert_eq!(fixture.schema, "sonium-qa.matrix-functions.v1");
    fixture
}

fn sort_spectrum(values: &mut [Complex64]) {
    values.sort_by(|left, right| {
        left.re
            .total_cmp(&right.re)
            .then(left.im.total_cmp(&right.im))
    });
}

/// Values-only spectra against the Wolfram {Re, Im}-sorted references.
fn check_nonsym_spectra(label: &str, case: &NonsymSpectraCase) {
    let matrix = dense(&case.a);
    let n = case.a.len();
    let mut values = nonsymmetric_eigenvalues(&matrix).expect("nonsymmetric_eigenvalues failed");
    assert_eq!(values.len(), n);
    let mut expected: Vec<Complex64> = case.eigenvalues.iter().map(parse_complex).collect();
    assert_eq!(expected.len(), n);
    sort_spectrum(&mut values);
    sort_spectrum(&mut expected);
    for (index, (got, want)) in values.iter().zip(expected.iter()).enumerate() {
        assert!(
            (got - want).norm() <= 1e-12 * want.norm().max(1.0),
            "{label} lambda[{index}]: {got:?} != {want:?}"
        );
    }
    // Trace identity against the same input both sides share.
    let trace: f64 = (0..n).map(|i| matrix[[i, i]]).sum();
    let sum: Complex64 = values.iter().copied().sum();
    assert!(
        (sum.re - trace).abs() <= 1e-9 * trace.abs().max(1.0) && sum.im.abs() <= 1e-9,
        "{label}: spectrum sum {sum:?} != trace {trace}"
    );
}

#[test]
fn nonsymmetric_spectrum_matches_wolfram() {
    let fixture = parse_matrix_functions();
    check_nonsym_spectra("nonsym_eig_4x4", &fixture.nonsym_eig_4x4);
    check_nonsym_spectra("companion_eig_3x3", &fixture.companion_eig_3x3);
}
